// ============================================================================
//  spawns/region_index.h  (G1, stage 1, Part B)
//
//  The Riverlands as a lookup: which of the footprint's 401 rectangles holds a point, and which of the 12 zones of influence (ZOIs) owns it.  The rectangles are
//  spawns/region_data.h (generated by tools/capture/gen_region.py from fixtures/region/*.json); this is an index over them, so that the 74,778 points of the
//  population chain and 10,000 NPCs' worth of questions cost a few comparisons each.
//
//  The index is a uniform grid of 8,192 cm squares over the footprint's bounding box; each square lists the rectangles that touch it (the footprint's, and
//  the per-ZOI ones, which tile the same area).  A rectangle is [x0, x1) x [y0, y1) in world cm, as in the data.  Nothing here reads a file or the game's export.
// ============================================================================
#pragma once

#include "spawns/region_data.h"

#include <cstdint>
#include <vector>

namespace aoc::worldd::spawns::region {

class Index {
public:
    /// The index over region_data.h, built once (thread-safe).
    static const Index& get();

    /// Builds an index over any rectangles (the tests build small ones).  `zoi_rows`/`zoi_rects` may be empty.
    Index(const Rect* rects, size_t rect_count, const ZoiRows* zois, size_t zoi_count, const Rect* zoi_rects, size_t zoi_rect_count);

    /// True when (x, y) (world cm) is inside the footprint.
    bool contains(double x, double y) const;
    /// The index in the ZOI table of the zone that owns (x, y); -1 outside every zone.
    int zoi_row(double x, double y) const;
    /// The owning zone's record guid; 0 outside every zone.
    uint64_t zoi_guid(double x, double y) const;
    /// The owning zone's record name; nullptr outside.
    const char* zoi_name(double x, double y) const;

    size_t rect_count() const { return rect_count_; }
    size_t zoi_count() const { return zoi_count_; }
    const ZoiRows* zois() const { return zois_; }
    /// The footprint's bounding box, world cm.
    int32_t min_x() const { return min_x_; }
    int32_t min_y() const { return min_y_; }
    int32_t max_x() const { return max_x_; }
    int32_t max_y() const { return max_y_; }
// C.Y.B x CoA

private:
    struct Grid {
        std::vector<uint32_t> offsets;   // per square, into `items` (size squares + 1)
        std::vector<uint32_t> items;     // rectangle indices
    };
    void build(Grid& grid, const Rect* rects, size_t count) const;
    int  find(const Grid& grid, const Rect* rects, double x, double y) const;

    const Rect*    rects_;
    size_t         rect_count_;
    const ZoiRows* zois_;
    size_t         zoi_count_;
    const Rect*    zoi_rects_;
    size_t         zoi_rect_count_;
    int32_t        min_x_ = 0, min_y_ = 0, max_x_ = 0, max_y_ = 0;
    int32_t        columns_ = 0, rows_ = 0;
    Grid           footprint_, zoi_;
    std::vector<int32_t> zoi_row_of_rect_;
};

/// The square a grid cell is, in cm.
inline constexpr int32_t kIndexSquareCm = 8192;

}  // namespace aoc::worldd::spawns::region
